<?php require __DIR__.'/../lib/bootstrap.php';require_admin();$pageTitle='Atividade';$logs=db()->query('SELECT a.*,u.name admin_name FROM audit_logs a LEFT JOIN admins u ON u.id=a.admin_id ORDER BY a.id DESC LIMIT 250')->fetchAll();$webhooks=db()->query('SELECT * FROM webhook_logs ORDER BY id DESC LIMIT 100')->fetchAll();require '_header.php';?>
<div class="admin-card"><div class="card-head"><div><h2>Auditoria</h2><p>Últimas ações administrativas e operacionais.</p></div></div><div class="table-wrap"><table><thead><tr><th>Data</th><th>Usuário</th><th>Ação</th><th>Entidade</th><th>IP</th></tr></thead><tbody><?php foreach($logs as $r):?><tr><td><?=e(dt_db_br($r['created_at']))?></td><td><?=e($r['admin_name']?:'Sistema')?></td><td><code><?=e($r['action'])?></code></td><td><?=e(($r['entity_type']?:'—').($r['entity_id']?' #'.$r['entity_id']:''))?></td><td><?=e($r['ip_address'])?></td></tr><?php endforeach;?></tbody></table></div></div>
<div class="admin-card"><div class="card-head"><div><h2>Webhooks Mercado Pago</h2><p>Histórico técnico das notificações recebidas.</p></div></div><div class="table-wrap"><table><thead><tr><th>Data</th><th>ID externo</th><th>Tipo</th><th>Assinatura</th><th>HTTP</th><th>Erro</th></tr></thead><tbody><?php if(!$webhooks):?><tr><td colspan="6">Nenhum webhook recebido.</td></tr><?php endif;?><?php foreach($webhooks as $w):?><tr><td><?=e(dt_db_br($w['created_at']))?></td><td><?=e($w['external_id'])?></td><td><?=e($w['event_type'])?></td><td><?= $w['signature_valid']?'✓':'—' ?></td><td><?=intval($w['http_status'])?></td><td><?=e($w['error_message']?:'—')?></td></tr><?php endforeach;?></tbody></table></div></div><?php require '_footer.php';?>
